/* W6 benchmark: unsigned arithmetic, shifts, table lookups (CRC-32 and FNV-1a over generated bytes). */
#include <stdio.h>
#include <stdint.h>
#define MB 32
#define SEED 2463534242u
static uint32_t table[256];
int main(void) {
  for (uint32_t i = 0; i < 256; i++) {
    uint32_t c = i;
    for (int k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320u ^ (c >> 1) : c >> 1;
    table[i] = c;
  }
  static unsigned char buf[1 << 16];
  uint32_t x = SEED, crc = 0xFFFFFFFFu;
  uint64_t fnv = 1469598103934665603ul;
  for (int blk = 0; blk < MB * 16; blk++) {
    for (int i = 0; i < (int)sizeof buf; i++) { x ^= x << 13; x ^= x >> 17; x ^= x << 5; buf[i] = (unsigned char)(x >> 24); }
    for (int i = 0; i < (int)sizeof buf; i++) {
      crc = table[(crc ^ buf[i]) & 0xFF] ^ (crc >> 8);
      fnv = (fnv ^ buf[i]) * 1099511628211ul;
    }
  }
  printf("crc32 %08x fnv %016lx\n", crc ^ 0xFFFFFFFFu, (unsigned long)fnv);
  return 0;
}
